{"writtenSpecifier":"./action-types","target":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b:module:a3cc8b741ad6599eb7b59c324f70edf2b26ee951047fccef439d9d30d767dfbf","status":"established"}},{"kind":"source-evidence","id":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b:source:fb139cec5c39b36c62c03d967becc1429e0b4a2c5958218f94efc80bf7516180","session":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b","method":"postcode/typescript-modules@12;typescript@6.0.3","path":"/Users/ronen/postcode/app/_investigation/module-assessment-sources/fsm-engine/src/dsl-impl.ts","contentDigest":"3be6a893e9bf834e503ad526c18efcb2de3a5016480f7442b7a09d7710486daa","start":0,"length":12414,"location":{"association":"file"},"configuredRoot":true,"compilerName":""/Users/ronen/postcode/app/_investigation/module-assessment-sources/fsm-engine/src/dsl-impl""}],"repositories":[],"selected":["session:c69416ea-8f6b-425d-b25c-5e6715ce001b:module:35c7001246df5fdcfd62f8b167bf2c5c7ff5bb105ade3ac84b5339479efdcc29"],"limitations":[]},{"status":"available","records":[{"kind":"captured-content","id":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b:captured-content:2223a19b7c84507271eb5dcafd0ce7c951322233ba64e5857e7344d6ae15d73d","session":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b","method":"postcode/subject-content@1","subject":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b:module:35c7001246df5fdcfd62f8b167bf2c5c7ff5bb105ade3ac84b5339479efdcc29","mapping":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b:source:fb139cec5c39b36c62c03d967becc1429e0b4a2c5958218f94efc80bf7516180","inputs":"session:c69416ea-8f6b-425d-b25c-5e6715ce001b:analysis-inputs:0c591e159fb9cc94c51cced81be30d6a75e79b3f279dc13bd4762ae01c2df91b","path":"/Users/ronen/postcode/app/_investigation/module-assessment-sources/fsm-engine/src/dsl-impl.ts","text":"import type { BeginAction, EntryAction, ExitAction, Guard, TransitionAction } from './action-types'
import type { EventMap, EventName } from './event-types'
import type { ExternalTransition, FsmDefinition, Table, Transition, EventTransitionTable } from './defs'
import type { FsmBuilder, FsmStateBuilder, FsmTransitionBuilder, FsmEventBuilder, FsmGuardedTransitionBuilder, FsmTransitionActionsBuilder } from './fsm-dsl'
import { FallbackState } from './defs'
import { FsmEngineMultipleStateDefinitionsError, FsmEngineMultipleEventDefinitionsError, FsmEngineNoDefinitionError, FsmEngineUnknownInitialStateError, FsmEngineUnknownTransitionStateError, FsmEngineUnreachableStateError, FsmEngineUnreachableTransitionError } from './fsm-error'

//----------------------------------------------------------------------------//
//                        FSM Builder DSL Classes                             //
//----------------------------------------------------------------------------//

type TargetRecord<State extends string, Events extends EventMap> = { fromState: State | FallbackState, event: EventName<Events>, toState: State }

function getOrInsert<K extends string, V>(table: Table<K, V>, key: K, defaultValue: V): V { return (table[key] ??= defaultValue) }
function tableValues<State extends string, Events extends EventMap, Context>(table: EventTransitionTable<State,Events,Context>): Transition<State, Events, Context, EventName<EventMap>>[] { return Object.values(table) as Transition<State, Events, Context, EventName<EventMap>>[] }

/**
 * DSL top-level
 */
export class FsmBuilderImpl<State extends string, Events extends EventMap, Context> implements FsmBuilder<State, Events, Context> {

  readonly #allStates          = new Set<State>()
  readonly #allEvents          = new Set<EventName<Events>>()
  readonly #seenFallbackEvents = new Set<EventName<Events>>()
  readonly #allTargets:          TargetRecord<State, Events>[]                                                      = []
  readonly #transitionTable:     Table<State, EventTransitionTable<State, Events, Context>>                         = {}
  readonly #beginTable:          Table<State, Table<EventName<Events>, Array<BeginAction<State, Events, Context>>>> = {}
  readonly #entryTable:          Table<State, Array<EntryAction<State, Events, Context>>>                           = {}
  readonly #exitTable:           Table<State, Array<ExitAction<State, Events, Context>>>                            = {}
  readonly #fallbackTransitions: EventTransitionTable<State, Events, Context>                                       = {}
  readonly #fallbackBegins:      Table<EventName<Events>, Array<BeginAction<State, Events, Context>>>               = {}

  #name:         string = 'FsmEngine'
  #initialState: State | null = null

  name(name: string): void {
    this.#name = name
  }

  initialState(state: State): void {
    this.#initialState = state
  }

  state(state: State, body?: (b: StateBuilder<State, Events, Context>) => void): void {
    if (this.#allStates.has(state)) {
      throw new FsmEngineMultipleStateDefinitionsError<State>(state)
    }
    this.#allStates.add(state)
    this.#initialState ??= state
    const s = new StateBuilder<State, Events, Context>(this, state)
    body?.(s)
  }

  fallback(
    eventOrEvents: EventName<Events> | readonly EventName<Events>[],
    body: (e: EventBuilder<State, Events, Context, EventName<Events>>) => void
  ): void {
    const events = (Array.isArray(eventOrEvents) ? eventOrEvents : [eventOrEvents]) as EventName<Events>[]

    for (const event of events) {
      if (this.#seenFallbackEvents.has(event)) {
        throw new FsmEngineMultipleEventDefinitionsError<State, Events>({ state: FallbackState, event })
      }
      this.#seenFallbackEvents.add(event)

      const e = new EventBuilder<State, Events, Context, typeof event>({ _root: this, _state: FallbackState }, event)
      body(e)
    }
  }


  _validate(): void {
    const allStates           = this.#allStates

    if (!this.#initialState) {
      throw new FsmEngineNoDefinitionError()
    }

    if (!this.#allStates.has(this.#initialState)) {
      throw new FsmEngineUnknownInitialStateError(this.#initialState)
    }

    // Validate that all target states exist
    const unknownTarget = this.#allTargets.find(t => !allStates.has(t.toState))
    if (unknownTarget) {
      throw new FsmEngineUnknownTransitionStateError<State, Events>(unknownTarget)
    }

    // validate that all states are reachable from the initial state via external transitions (or implicitly via fallbacks)
    const externalTransitions = (table?: EventTransitionTable<State, Events, Context>): ExternalTransition<State, Events, Context, EventName<Events>>[] => {
      if (!table) { return [] }
      return tableValues(table).flat().filter((t: Transition<State, Events, Context, EventName<Events>>) => t.kind === 'external')
    }
    const seen = new Set<State>()
    const traverse = (state: State): void => {
      if (seen.has(state)) { return }
      seen.add(state)
      externalTransitions(this.#transitionTable[state]).forEach(t => traverse(t.target))
    }
    traverse(this.#initialState)
    externalTransitions(this.#fallbackTransitions).forEach(t => traverse(t.target))

    const unreachableState = [...allStates.values()].find(s => !seen.has(s))
    if (unreachableState) {
      throw new FsmEngineUnreachableStateError<State>({ initialState: this.#initialState, unreachableState })
    }

  }

  _compile(): FsmDefinition<State, Events, Context> {
    return {
      name:                this.#name,
      initialState:        this.#initialState!,
      allStates:           this.#allStates,
      allEvents:           this.#allEvents,
      transitionTable:     this.#transitionTable,
      beginTable:          this.#beginTable,
      entryTable:          this.#entryTable,
      exitTable:           this.#exitTable,
      fallbackTransitions: this.#fallbackTransitions,
      fallbackBegins:      this.#fallbackBegins,
    }
  }


  // Internal API used by builders
  _addEvent(event: EventName<Events>): void {
    this.#allEvents.add(event)
  }

  _addTarget(record: TargetRecord<State, Events>): void {
    this.#allTargets.push(record)
  }

  _pushTransition<K extends EventName<Events>>(state: State | FallbackState, event: K, transition: Transition<State, Events, Context, K>): void {
    const transitions    = this.#transitionsFor(state, event)
    const lastTransition = transitions.at(-1)
    if (lastTransition && lastTransition.guards.length === 0) {
      throw new FsmEngineUnreachableTransitionError<State, Events>({ fromState: state, event, toState: transition.kind === 'external' ? transition.target : undefined })
    }
    transitions.push(transition)
  }

  _pushBeginAction<K extends EventName<Events>>(state: State | FallbackState, event: K, action: BeginAction<State, Events, Context, K>): void {
    const entryBeginMap = state === FallbackState ? this.#fallbackBegins : getOrInsert(this.#beginTable, state, {})
    const actions       = getOrInsert(entryBeginMap, event, [])
    actions.push(action as BeginAction<State, Events, Context>)
  }

  _pushEntryAction(state: State, action: EntryAction<State, Events, Context>): void {
    const actions = getOrInsert(this.#entryTable, state, [])
    actions.push(action)
  }

  _pushExitAction(state: State, action: ExitAction<State, Events, Context>): void {
    const actions = getOrInsert(this.#exitTable, state, [])
    actions.push(action)
  }

  #transitionsFor<K extends EventName<Events>>(state: State | FallbackState, event: K): Transition<State, Events, Context, K>[] {
    const entryTransitionMap = state === FallbackState ? this.#fallbackTransitions : getOrInsert(this.#transitionTable, state, {})
    return entryTransitionMap[event] ??= []
  }
}

class StateBuilder<State extends string, Events extends EventMap, Context> implements FsmStateBuilder<State, Events, Context> {

  readonly _root: FsmBuilderImpl<State, Events, Context>
  readonly _state: State
  readonly #seenEvents = new Set<EventName<Events>>()

  constructor(root: FsmBuilderImpl<State, Events, Context>, state: State) {
    this._root = root
    this._state = state
  }

  onEnter(action: EntryAction<State, Events, Context>): void {
    this._root._pushEntryAction(this._state, action)
  }

  onExit(action: ExitAction<State, Events, Context>): void {
    this._root._pushExitAction(this._state, action)
  }

  event(
    eventOrEvents: EventName<Events> | readonly EventName<Events>[],
    body: (e: EventBuilder<State, Events, Context, EventName<Events>>) => void
  ): void {
    const events = (Array.isArray(eventOrEvents) ? eventOrEvents : [eventOrEvents]) as EventName<Events>[]

    for (const event of events) {
      if (this.#seenEvents.has(event)) {
        throw new FsmEngineMultipleEventDefinitionsError<State, Events>({ state: this._state, event })
      }
      this.#seenEvents.add(event)

      const e = new EventBuilder<State, Events, Context, typeof event>(this, event)
      body(e)
    }
  }

}

type FallbackBuilder<State extends string, Events extends EventMap, Context> = { _root: FsmBuilderImpl<State, Events, Context>, _state: FallbackState }

abstract class TransitionBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> implements FsmTransitionBuilder<State, Events, Context, K> {

  protected readonly _parent: StateBuilder<State, Events, Context> | FallbackBuilder<State, Events, Context>
  protected readonly _guards: Guard<State, Events, Context, K>[] = []

  readonly _event: K
  _transition?: Transition<State, Events, Context, K>

  get _state(): State | FallbackState { return this._parent._state }
  get _root(): FsmBuilderImpl<State, Events, Context> { return this._parent._root }

  constructor(parent: StateBuilder<State, Events, Context> | FallbackBuilder<State, Events, Context>, event: K) {
    this._parent = parent
    this._event = event
    this._root._addEvent(event)
  }

  toState(target: State, body?: (t: TransitionActionsBuilder<State, Events, Context, K>) => void): void {
    this._root._addTarget({ fromState: this._state, event: this._event, toState: target })
    this._transition = { kind: 'external', target, guards: this._guards, actions: [] }
    this.#pushTransition()
    const t = new TransitionActionsBuilder(this._transition)
    body?.(t)
  }

  stay(body?: (t: TransitionActionsBuilder<State, Events, Context, K>) => void): void {
    this._transition = { kind: 'internal', guards: this._guards, actions: [] }
    this.#pushTransition()
    const t = new TransitionActionsBuilder(this._transition)
    body?.(t)
  }

  #pushTransition(): void {
    this._root._pushTransition(this._state, this._event, this._transition!)
  }

}

class EventBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> extends TransitionBuilder<State, Events, Context, K> implements FsmEventBuilder<State, Events, Context, K> {

  begin(action: BeginAction<State, Events, Context, K>): void {
    this._root._pushBeginAction(this._state, this._event, action)
  }

  when(cond: Guard<State, Events, Context, K>): GuardedTransitionBuilder<State, Events, Context, K> {
    const e = new GuardedTransitionBuilder<State, Events, Context, K>(this._parent, this._event, cond)
    return e
  }

}

class GuardedTransitionBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> extends TransitionBuilder<State, Events, Context, K> implements FsmGuardedTransitionBuilder<State, Events, Context, K> {
  constructor(parent: StateBuilder<State, Events, Context> | FallbackBuilder<State, Events, Context>, event: K, firstGuard: Guard<State, Events, Context, K>) {
    super(parent, event)
    this._guards.push(firstGuard)
  }

  when(cond: Guard<State, Events, Context, K>): this {
    this._guards.push(cond)
    return this
  }
}

class TransitionActionsBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> implements FsmTransitionActionsBuilder<State, Events, Context, K> {
  readonly #transition: Transition<State, Events, Context, K>
  constructor(transition: Transition<State, Events, Context, K>) {
    this.#transition = transition
  }
  action(action: TransitionAction<State, Events, Context, K>): void {
    this.#transition.actions.push(action)
  }
}
