//                          FSM Timer Registry                                //
//
// A utility for managing multiple timers by key, with support for both
// relative (ms) and absolute (deadline) timers. Provides methods to
// schedule, cancel, and cancel all timers. Intended for use by the FSM
// Action API, but there's nothing specific to the FSM here.
//----------------------------------------------------------------------------//

export type TimerKey = string | symbol

export type TimerSpec =
  | { ms: number; deadline?: never }
  | { deadline: number; ms?: never }

export type ScheduleParams = {
  key: TimerKey
} & TimerSpec

export class TimerRegistry {
  readonly #timers = new Map<TimerKey, ReturnType<typeof setTimeout>>()

  schedule(params: ScheduleParams, run: () => void): void {
    const { key } = params

    this.cancel(key)

    const delay = this.#computeDelay(params)
    if (delay === Infinity) return

    const handle = setTimeout(() => {
      this.#timers.delete(key)
      run()
    }, delay)

    this.#timers.set(key, handle)
  }

  cancel(key: TimerKey): void {
    const handle = this.#timers.get(key)
    if (!handle) return
    clearTimeout(handle)
    this.#timers.delete(key)
  }

  cancelAll(): void {
    for (const handle of this.#timers.values()) clearTimeout(handle)
    this.#timers.clear()
  }

  #computeDelay(params: TimerSpec): number {
    if ('ms' in params && params.ms !== undefined) {
      const ms = params.ms
      if (ms === Infinity) return Infinity
      if (!Number.isFinite(ms)) throw new Error(`fsm.timer: ms must be finite (or Infinity), got ${String(ms)}`)
      return Math.max(0, ms)
    }

    const deadline = params.deadline
    if (deadline === Infinity) return Infinity
    if (!Number.isFinite(deadline)) throw new Error(`fsm.timer: deadline must be finite (or Infinity), got ${String(deadline)}`)

    // Domain guard: deadline should be in performance.now() time domain, not epoch ms
    if (deadline > Date.now()) {
      throw new Error(
        'fsm.timer: deadline looks like epoch ms (Date.now()). ' +
        'Expected deadline in performance.now() time domain.'
      )
    }

    return Math.max(0, deadline - performance.now())
  }
}

