if (import.meta.vitest) {
  const { beforeEach, afterEach, describe, it, expect, vi } = import.meta.vitest

  describe('TimerRegistry', () => {
    beforeEach(() => {
      vi.useFakeTimers()
    })

    afterEach(() => {
      vi.useRealTimers()
    })

    it('fires ms timers', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', ms: 50 }, run)

      vi.advanceTimersByTime(49)
      expect(run).not.toHaveBeenCalled()

      vi.advanceTimersByTime(1)
      expect(run).toHaveBeenCalledTimes(1)
    })

    it('clamps negative ms to 0 (fires on next tick)', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', ms: -10 }, run)

      vi.advanceTimersByTime(0)
      expect(run).toHaveBeenCalledTimes(1)
    })

    it('replaces an existing timer with the same key', () => {
      const timers = new TimerRegistry()
      const a = vi.fn()
      const b = vi.fn()

      timers.schedule({ key: 'k', ms: 50 }, a)
      timers.schedule({ key: 'k', ms: 100 }, b)

      vi.advanceTimersByTime(60)
      expect(a).not.toHaveBeenCalled()
      expect(b).not.toHaveBeenCalled()

      vi.advanceTimersByTime(40)
      expect(a).not.toHaveBeenCalled()
      expect(b).toHaveBeenCalledTimes(1)
    })

    it('cancel prevents firing', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', ms: 20 }, run)
      timers.cancel('k')

      vi.advanceTimersByTime(100)
      expect(run).not.toHaveBeenCalled()
    })

    it('cancelAll prevents all firing', () => {
      const timers = new TimerRegistry()
      const a = vi.fn()
      const b = vi.fn()

      timers.schedule({ key: 'a', ms: 10 }, a)
      timers.schedule({ key: 'b', ms: 20 }, b)

      timers.cancelAll()

      vi.advanceTimersByTime(100)
      expect(a).not.toHaveBeenCalled()
      expect(b).not.toHaveBeenCalled()
    })

    it('deadline uses performance.now() domain', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', deadline: performance.now() + 50 }, run)

      vi.advanceTimersByTime(49)
      expect(run).not.toHaveBeenCalled()

      vi.advanceTimersByTime(1)
      expect(run).toHaveBeenCalledTimes(1)
    })

    it('deadline in the past fires immediately', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', deadline: performance.now() - 1 }, run)

      vi.advanceTimersByTime(0)
      expect(run).toHaveBeenCalledTimes(1)
    })

    it('throws if deadline looks like epoch ms (Date.now domain)', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      expect(() => {
        timers.schedule({ key: 'k', deadline: Date.now() + 1000 }, run)
      }).toThrow(/epoch ms|Date\.now/i)

      vi.advanceTimersByTime(10_000)
      expect(run).not.toHaveBeenCalled()
    })

    it('ms: Infinity never fires', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', ms: Infinity }, run)

      vi.advanceTimersByTime(10_000)
      expect(run).not.toHaveBeenCalled()
    })

    it('deadline: Infinity never fires', () => {
      const timers = new TimerRegistry()
      const run = vi.fn()

      timers.schedule({ key: 'k', deadline: Infinity }, run)

      vi.advanceTimersByTime(10_000)
      expect(run).not.toHaveBeenCalled()
    })

    it('can reschedule the same key from inside the callback', () => {
      const timers = new TimerRegistry()
      const calls: string[] = []

      const run1 = (): void => {
        calls.push('run1')
        timers.schedule({ key: 'k', ms: 10 }, run2)
      }

      const run2 = (): void => {
        calls.push('run2')
      }

      timers.schedule({ key: 'k', ms: 0 }, run1)

      vi.advanceTimersByTime(0)
      expect(calls).toEqual(['run1'])

      vi.advanceTimersByTime(10)
      expect(calls).toEqual(['run1', 'run2'])
    })
  })
